def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = tuple(h[1] for h in history)
    my = tuple(h[0] for h in history)

    # consecutive opponent defections at the tail
    tail_def = 0
    for a in reversed(opp):
        if a == 'D':
            tail_def += 1
        else:
            break

    # consecutive opponent cooperations at the tail
    tail_coop = 0
    for a in reversed(opp):
        if a == 'C':
            tail_coop += 1
        else:
            break

    opp_coop = opp.count('C')
    opp_coop_rate = opp_coop / n

    # If opponent has never defected: cooperate, but grab last two rounds
    # and occasionally probe to test for exploitability.
    if opp_coop == n:
        if n >= 98:
            return 'D'
        if n >= 3 and n % 11 == 0 and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Opponent is exploiting us heavily (we cooperate, they defect).
    # Punish with a short retaliation, then return to reciprocity.
    me_last = my[-1]
    opp_last = opp[-1]

    if opp_last == 'D':
        # If they just started defecting after long cooperation, forgive once.
        if tail_def == 1 and tail_coop >= 3 and opp_coop_rate > 0.6:
            # Forgive, but if they persist we'll strike back next round.
            return 'C'
        # Retaliate while they keep defecting.
        if tail_def >= 2:
            return 'D'
        # Isolated defection: retaliate once with high probability.
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Opponent cooperated last round.
    # If they have been mostly cooperative, reciprocate, with mild probing.
    if opp_coop_rate >= 0.6:
        # Late-game defection to exploit a soft opponent.
        if n >= 97:
            return 'D'
        # Rare probe when we've been cooperating a while.
        if me_last == 'C' and tail_coop >= 4 and n % 9 == 0 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Opponent's cooperation is middling.
    # Punish recent defections harder, otherwise cooperate.
    recent_len = min(6, n)
    recent_def = 0
    for a in opp[-recent_len:]:
        if a == 'D':
            recent_def += 1

    if recent_def * 2 >= recent_len:
        return 'D'

    # If we just defected and they still cooperated, take advantage once.
    if me_last == 'D' and opp_last == 'C' and n < 95:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    return 'C'
